CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('admin','user') NOT NULL DEFAULT 'admin', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS projects (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, description TEXT NULL, status ENUM('planned','active','archived') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dispatch_centers (id INT AUTO_INCREMENT PRIMARY KEY, project_id INT NOT NULL, name VARCHAR(160) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS station_types (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL UNIQUE, slug VARCHAR(180) NOT NULL UNIQUE, active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS stations (id INT AUTO_INCREMENT PRIMARY KEY, project_id INT NOT NULL, dispatch_center_id INT NULL, station_type_id INT NOT NULL, name VARCHAR(190) NOT NULL, address VARCHAR(255) NULL, latitude DECIMAL(10,7) NULL, longitude DECIMAL(10,7) NULL, planned_status ENUM('planned','under_construction','existing') NOT NULL DEFAULT 'planned', notes TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE, FOREIGN KEY(dispatch_center_id) REFERENCES dispatch_centers(id) ON DELETE SET NULL, FOREIGN KEY(station_type_id) REFERENCES station_types(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vehicle_types (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(190) NOT NULL UNIQUE, slug VARCHAR(210) NOT NULL UNIQUE, category VARCHAR(120) NULL, station_type VARCHAR(160) NULL, required_expansion VARCHAR(190) NULL, personnel_required INT NOT NULL DEFAULT 0, required_training VARCHAR(255) NULL, credits INT NOT NULL DEFAULT 0, lss_vehicle_type_id INT NULL, active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS planned_station_vehicles (id INT AUTO_INCREMENT PRIMARY KEY, station_id INT NOT NULL, vehicle_type_id INT NOT NULL, quantity INT NOT NULL DEFAULT 1, notes TEXT NULL, FOREIGN KEY(station_id) REFERENCES stations(id) ON DELETE CASCADE, FOREIGN KEY(vehicle_type_id) REFERENCES vehicle_types(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS expansions (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(190) NOT NULL, slug VARCHAR(210) NOT NULL UNIQUE, station_type VARCHAR(160) NULL, cost INT NOT NULL DEFAULT 0, build_time VARCHAR(80) NULL, unlocks TEXT NULL, notes TEXT NULL, active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS planned_station_expansions (id INT AUTO_INCREMENT PRIMARY KEY, station_id INT NOT NULL, expansion_id INT NOT NULL, quantity INT NOT NULL DEFAULT 1, FOREIGN KEY(station_id) REFERENCES stations(id) ON DELETE CASCADE, FOREIGN KEY(expansion_id) REFERENCES expansions(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS training_types (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(190) NOT NULL, slug VARCHAR(210) NOT NULL, organisation VARCHAR(120) NULL, school VARCHAR(160) NULL, duration_days INT NOT NULL DEFAULT 0, UNIQUE KEY uniq_training (slug, organisation, school)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS training_vehicle_requirements (id INT AUTO_INCREMENT PRIMARY KEY, training_type_id INT NOT NULL, vehicle_name VARCHAR(190) NOT NULL, FOREIGN KEY(training_type_id) REFERENCES training_types(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS station_build_costs (id INT AUTO_INCREMENT PRIMARY KEY, station_count INT NOT NULL, station_type VARCHAR(180) NOT NULL, cost INT NOT NULL, UNIQUE KEY uniq_cost (station_count, station_type)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS app_meta (meta_key VARCHAR(100) PRIMARY KEY, meta_value TEXT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
    id INT AUTO_INCREMENT PRIMARY KEY,
    import_type VARCHAR(80) NOT NULL,
    file_name VARCHAR(255) NULL,
    processed INT NOT NULL DEFAULT 0,
    created_count INT NOT NULL DEFAULT 0,
    updated_count INT NOT NULL DEFAULT 0,
    skipped_count INT NOT NULL DEFAULT 0,
    error_count INT NOT NULL DEFAULT 0,
    errors_json JSON NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
